    if (ocgs == null)
    {
        return new String[0];
    }
    int size = ocgs.size();
    String[] groups = new String[size];
    for (int i = 0; i < size; i++)
    {
        COSBase obj = ocgs.get(i);
        COSDictionary ocg = toDictionary(obj);
        if (ocg == null)
        {
            groups[i] = "";
        }
        else
        {
            groups[i] = ocg.getString(COSName.NAME);
        }
    }
    return groups;
}

