public void writeXML(Writer output) throws IOException
{
    PDFileSpecification fs = this.getFile();
    if (fs != null)
    {
        output.write("<f href=\"" + fs.getFile() + "\" />\n");
    }
    COSArray ids = this.getID();
    if (ids != null)
    {
        COSString original = (COSString) ids.getObject(0);
        COSString modified = (COSString) ids.getObject(1);
        output.write("<ids original=\"" + original.toHexString() + "\" ");
        output.write("modified=\"" + modified.toHexString() + "\" />\n");
    }
    List<FDFField> fields = getFields();
    if (fields != null && fields.size() > 0)
    {
        output.write("<fields>\n");
        for (FDFField field : fields)
        {
            field.writeXML(output);
        }
        output.write("</fields>\n");
    }
}

public AcroFormGenerateAppearancesProcessor(PDDocument document)
{ 
    super(document); 
}

public void process() {
    /*
     * Get the AcroForm in it's current state.
     *
     * Also note: getAcroForm() applies a default fixup which this processor
     * is part of. So keep the null parameter otherwise this will end
     * in an endless recursive call
     */
    PDAcroForm acroForm = document.getDocumentCatalog().getAcroForm(null);

    if (acroForm != null)
    {            
        try
        {
            LOG.debug("trying to generate appearance streams for fields as NeedAppearances is true()");
            acroForm.refreshAppearances();
            acroForm.setNeedAppearances(false);
        }
        catch (IOException | IllegalArgumentException ex)
        {
            LOG.debug("couldn't generate appearance stream for some fields - check output");
            LOG.debug(ex.getMessage());
        }
    } 
}

public PDDocumentCatalog getDocumentCatalog()
{
    if (documentCatalog == null)
    {
        COSDictionary trailer = document.getTrailer();
        COSDictionary dictionary = trailer.getCOSDictionary(COSName.ROOT);
        if (dictionary != null)
        {
            documentCatalog = new PDDocumentCatalog(this, dictionary);
        }
        else
        {
            documentCatalog = new PDDocumentCatalog(this);
        }
    }
    return documentCatalog;
}

public PDAcroForm getAcroForm(PDDocumentFixup acroFormFixup)
{
    if (acroFormFixup != null && acroFormFixup != acroFormFixupApplied)
    {
        acroFormFixup.apply();
        cachedAcroForm = null;
        acroFormFixupApplied =  acroFormFixup;
    }
    else if (acroFormFixupApplied != null)
    {
        LOG.debug("AcroForm content has already been retrieved with fixes applied - original content changed because of that");
    }
    if (cachedAcroForm == null)
    {
        COSDictionary dict = root.getCOSDictionary(COSName.ACRO_FORM);
        cachedAcroForm = dict == null ? null : new PDAcroForm(document, dict);
    }
    return cachedAcroForm;
}

