protected BufferedImage toRGBImageAWT(WritableRaster raster, ColorSpace colorSpace)
{
    //
    // WARNING: this method is performance sensitive, modify with care!
    //

    // ICC Profile color transforms are only fast when performed using ColorConvertOp
    ColorModel colorModel = new ComponentColorModel(colorSpace,
        false, false, Transparency.OPAQUE, raster.getDataBuffer().getDataType());

    BufferedImage src = new BufferedImage(colorModel, raster, false, null);
    BufferedImage dest = new BufferedImage(raster.getWidth(), raster.getHeight(),
                                           BufferedImage.TYPE_INT_RGB);
    if (src.getWidth() == 1 || src.getHeight() == 1)
    {
        // PDFBOX-5051: ColorConvertOp is too slow for tiny images. But we can't use drawImage()
        // for all images because it is slower when used for all images.
        // Re quality & speed: the quality gold standard is setRGB(getRGB()) but this is also 
        // the slowest. drawImage() is identical in quality (but faster) except for ICC based
        // images with 1 component. ColorConvertOp is fastest except for small images, there's
        // somehow a slowness "price" paid per call and the quality is slightly flawed sometimes,
        // and rendering hints are ignored.
        // All the above tested with jdk8 and LCMS.
        Graphics g2d = dest.getGraphics();
        g2d.drawImage(src, 0, 0, null);
        g2d.dispose();
        return dest;
    }
    colorConvertOp.filter(src, dest);
    return dest;
}

public DecodeResult decode(InputStream encoded, OutputStream decoded,
                                     COSDictionary parameters, int index) throws IOException
{
    int dupAmount;
    byte[] buffer = new byte[128];
    while ((dupAmount = encoded.read()) != -1 && dupAmount != RUN_LENGTH_EOD)
    {
        if (dupAmount <= 127)
        {
            int amountToCopy = dupAmount + 1;
            int compressedRead;
            while (amountToCopy > 0)
            {
                compressedRead = encoded.read(buffer, 0, amountToCopy);
                // EOF reached?
                if (compressedRead == -1)
                {
                    break;
                }
                decoded.write(buffer, 0, compressedRead);
                amountToCopy -= compressedRead;
            }
        }
        else
        {
            int dupByte = encoded.read();
            // EOF reached?
            if (dupByte == -1)
            {
                break;
            }
            for (int i = 0; i < 257 - dupAmount; i++)
            {
                decoded.write(dupByte);
            }
        }
    }
    return new DecodeResult(parameters);
}

protected void encode(InputStream input, OutputStream encoded, COSDictionary parameters)
        throws IOException
{
    // Not used in PDFBox except for testing the decoder.
    int lastVal = -1;
    int byt;
    int count = 0;
    boolean equality = false;

    // buffer for "unequal" runs, size between 2 and 128
    byte[] buf = new byte[128];

    while ((byt = input.read()) != -1)
    {
        if (lastVal == -1)
        {
            // first time
            lastVal = byt;
            count = 1;
        }
        else
        {
            if (count == 128)
            {
                if (equality)
                {
                    // max length of equals
                    encoded.write(129); // = 257 - 128
                    encoded.write(lastVal);
                }
                else
                {
                    // max length of unequals
                    encoded.write(127);
                    encoded.write(buf, 0, 128);
                }
                equality = false;
                lastVal = byt;
                count = 1;
            }
            else if (count == 1)
            {
                if (byt == lastVal)
                {
                    equality = true;
                }
                else
                {
                    buf[0] = (byte) lastVal;
                    buf[1] = (byte) byt;
                    lastVal = byt;
                }
                count = 2;
            }
            else
            {
                // 1 < count < 128
                if (byt == lastVal)
                {
                    if (equality)
                    {
                        ++count;
                    }
                    else
                    {
                        // write all we got except the last
                        encoded.write(count - 2);
                        encoded.write(buf, 0, count - 1);
                        count = 2;
                        equality = true;
                    }
                }
                else
                {
                    if (equality)
                    {
                        // equality ends here
                        encoded.write(257 - count);
                        encoded.write(lastVal);
                        equality = false;
                        count = 1;
                    }
                    else
                    {
                        buf[count] = (byte) byt;
                        ++count;
                    }
                    lastVal = byt;
                }
            }
        }
    }
    if (count > 0)
    {
        if (count == 1)
        {
            encoded.write(0);
            encoded.write(lastVal);
        }
        else if (equality)
        {
            encoded.write(257 - count);
            encoded.write(lastVal);
        }
        else
        {
            encoded.write(count - 1);
            encoded.write(buf, 0, count);
        }
    }
    encoded.write(RUN_LENGTH_EOD);
}

