public T getValue()
{
    return value;
}

public void setValue(T value)
{
    if (this.value != null)
    {
        throw new IllegalStateException("Value already set for this trie node");
    }
    this.value = value;
}

public void addPath(T value, byte[]... parts)
{
    int depth = 0;
    ByteTrieNode<T> node = root;
    for (byte[] part : parts)
    {
        for (byte b : part)
        {
            ByteTrieNode<T> child = node.children.get(b);
            if (child == null)
            {
                child = new ByteTrieNode<>();
                node.children.put(b, child);
            }
            node = child;
            depth++;
        }
    }
    node.setValue(value);
    maxDepth = Math.max(maxDepth, depth);
}

public T find(byte[] bytes)
{
    ByteTrieNode<T> node = root;
    T val = node.getValue();
    for (byte b : bytes)
    {
        ByteTrieNode<T> child = node.children.get(b);
        if (child == null)
        {
            break;
        }
        node = child;
        if (node.getValue() != null)
        {
            val = node.getValue();
        }
    }
    return val;
}

public int getMaxDepth()
{
    return maxDepth;
}

public void setDefaultValue(T defaultValue)
{
    root.setValue(defaultValue);
}

