{
    if (LOW <= val && val <= HIGH)
    {
        int index = (int) val - LOW;
        // no synchronization needed
        if (STATIC[index] == null)
        {
            STATIC[index] = new COSInteger(val, true);
        }
        return STATIC[index];
    }
    return new COSInteger(val, true);
}

