static PDImageXObject prepareImageXObject(PDDocument document,
        byte [] byteArray, int width, int height, int bitsPerComponent, 
        PDColorSpace initColorSpace) throws IOException
{
    //pre-size the output stream to half of the input
    ByteArrayOutputStream baos = new ByteArrayOutputStream(byteArray.length/2);

    Filter filter = FilterFactory.INSTANCE.getFilter(COSName.FLATE_DECODE);
    filter.encode(new ByteArrayInputStream(byteArray), baos, new COSDictionary(), 0);

    ByteArrayInputStream encodedByteStream = new ByteArrayInputStream(baos.toByteArray());
    return new PDImageXObject(document, encodedByteStream, COSName.FLATE_DECODE, 
            width, height, bitsPerComponent, initColorSpace);
}

public PDColorSpace getColorSpace() throws IOException
{
    if (colorSpace == null)
    {
        COSBase cosBase = getCOSObject().getItem(COSName.COLORSPACE, COSName.CS);
        if (cosBase != null)
        {
            COSObject indirect = null;
            if (cosBase instanceof COSObject &&
                    resources != null && resources.getResourceCache() != null)
            {
                // PDFBOX-4022: use the resource cache because several images
                // might have the same colorspace indirect object.
                indirect = (COSObject) cosBase;
                colorSpace = resources.getResourceCache().getColorSpace(indirect);
                if (colorSpace != null)
                {
                    return colorSpace;
                }
            }
            colorSpace = PDColorSpace.create(cosBase, resources);
            if (indirect != null)
            {
                resources.getResourceCache().put(indirect, colorSpace);
            }
        }
        else if (isStencil())
        {
            // stencil mask color space must be gray, it is often missing
            colorSpace = PDDeviceGray.INSTANCE;
        }
        else
        {
            initJPXValues();
        }
        if (colorSpace == null)
        {
            // an image without a color space is always broken
            throw new IOException("could not determine color space");
        }
    }
    return colorSpace;
}

