public static PDFunction create( COSBase function ) throws IOException
{
    if (function == COSName.IDENTITY)
    {
        return new PDFunctionTypeIdentity(null);
    }

    COSBase base = function;
    if (function instanceof COSObject)
    {
        base = ((COSObject) function).getObject();
    }
    if (!(base instanceof COSDictionary))
    {
        throw new IOException("Error: Function must be a Dictionary, but is " +
                (base == null ? "(null)" : base.getClass().getSimpleName()));
    }
    COSDictionary functionDictionary = (COSDictionary) base;
    int functionType = functionDictionary.getInt(COSName.FUNCTION_TYPE);
    switch (functionType)
    {
        case 0:
            return new PDFunctionType0(functionDictionary);
        case 2:
            return new PDFunctionType2(functionDictionary);
        case 3:
            return new PDFunctionType3(functionDictionary);
        case 4:
            return new PDFunctionType4(functionDictionary);
        default:
            throw new IOException("Error: Unknown function type " + functionType);
    }
}

public PDColorSpace getAlternateColorSpace() throws IOException
{
    COSBase alternate = stream.getCOSObject().getDictionaryObject(COSName.ALTERNATE);
    COSArray alternateArray;
    if(alternate == null)
    {
        alternateArray = new COSArray();
        int numComponents = getNumberOfComponents();
        COSName csName;
        switch (numComponents)
        {
            case 1:
                csName = COSName.DEVICEGRAY;
                break;
            case 3:
                csName = COSName.DEVICERGB;
                break;
            case 4:
                csName = COSName.DEVICECMYK;
                break;
            default:
                throw new IOException("Unknown color space number of components:" + numComponents);
        }
        alternateArray.add(csName);
    }
    else
    {
        if(alternate instanceof COSArray)
        {
            alternateArray = (COSArray)alternate;
        }
        else if(alternate instanceof COSName)
        {
            alternateArray = new COSArray();
            alternateArray.add(alternate);
        }
        else
        {
            throw new IOException("Error: expected COSArray or COSName and not " +
                alternate.getClass().getName());
        }
    }
    return PDColorSpace.create(alternateArray);
}

