private float getWidthRot(float rotation)
{
    if (Float.compare(rotation, 90) == 0 || Float.compare(rotation, 270) == 0)
    {
        return Math.abs(endY - textMatrix.getTranslateY());
    }
    else
    {
        return Math.abs(endX - textMatrix.getTranslateX());
    }
}

