public Integer getLowerLimit()
{
    Integer retval = null;
    COSArray arr = node.getCOSArray(COSName.LIMITS);
    if( arr != null && arr.get(0) != null )
    {
        retval = arr.getInt( 0 );
    }
    return retval;
}

public Integer getUpperLimit()
{
    Integer retval = null;
    COSArray arr = node.getCOSArray(COSName.LIMITS);
    if( arr != null && arr.get(1) != null )
    {
