    XPath xpath = XPathFactory.newInstance().newXPath();
    try
    {
        setDefaultAppearance(xpath.evaluate("defaultappearance", element));
        setDefaultStyle(xpath.evaluate("defaultstyle", element));
    }
    catch (XPathExpressionException ex)
    {
