public static FontMetrics getAFM(String fontName)
{
    FontName baseName = ALIASES.get(fontName);
    if (baseName == null)
    {
        return null;
    }

    if (FONTS.get(baseName) == null)
    {
        synchronized (FONTS)
        {
            if (FONTS.get(baseName) == null)
            {
                try
                {
                    loadMetrics(baseName);
                }
                catch (IOException e)
                {
                    throw new IllegalArgumentException(e);
                }
            }
        }
    }

    return FONTS.get(baseName);
}

