protected float interpolate(float x, float xRangeMin, float xRangeMax, float yRangeMin, float yRangeMax) 
{
    if (xRangeMax == xRangeMin)
    {
        // PDFBOX-5593 / PR #162
        return yRangeMin;
    }
    return yRangeMin + ((x - xRangeMin) * (yRangeMax - yRangeMin)/(xRangeMax - xRangeMin));
}

