            .max(Long::compare).orElse(0L);
    long highestXRefObjectNumber = getDocument().getHighestXRefObjectNumber();
    getDocument().setHighestXRefObjectNumber(
            Math.max(highestXRefObjectNumber, highestImportedNumber));
}

