private boolean setPermissionBit( int bit, boolean value )
{
    int permissions = bytes;
    if( value )
    {
        permissions = permissions | (1 << (bit-1));
    }
    else
    {
        permissions = permissions & (~(1 << (bit - 1)));
    }
    bytes = permissions;

    return (bytes & (1 << (bit-1))) != 0;
}

