public byte[] getUserKey() throws IOException
{
    byte[] u = null;
    COSString user = (COSString) dictionary.getDictionaryObject( COSName.U );
    if( user != null )
    {
        u = user.getBytes();
        int r = getRevision();
        if (r <= 4)
        {
            u = Arrays.copyOf(u, 32);
        }
        else if (r == 5 || r == 6)
        {
            u = Arrays.copyOf(u, 48);
        }
    }
    return u;
}

