public void addEntry(XReferenceEntry entry)
{
    if (objectNumbers.contains(entry.getReferencedKey().getNumber()))
    {
        return;
    }
    objectNumbers.add(entry.getReferencedKey().getNumber());
    streamData.add(entry);
}

