public Raster getRaster(int x, int y, int w, int h)
{
    // create writable raster
    WritableRaster raster = getColorModel().createCompatibleWritableRaster(w, h);
    boolean useBackground;
    int[] data = new int[w * h * 4];
    float[] values = new float[2];
    for (int j = 0; j < h; j++)
    {
        for (int i = 0; i < w; i++)
        {
            useBackground = false;
            values[0] = x + i;
            values[1] = y + j;
            rat.transform(values, 0, values, 0, 1);
            double inputValue = x1x0 * (values[0] - coords[0]) + y1y0 * (values[1] - coords[1]);
            // TODO this happens if start == end, see PDFBOX-1442
            if (Double.compare(denom, 0) == 0)
            {
                if (getBackground() == null)
                {
                    continue;
                }
                useBackground = true;
            }
            else
            {
                inputValue /= denom;
            }
            // input value is out of range
            if (inputValue < 0)
            {
                // the shading has to be extended if extend[0] == true
                if (extend[0])
                {
                    inputValue = domain[0];
                }
                else
                {
                    if (getBackground() == null)
                    {
                        continue;
                    }
                    useBackground = true;
                }
            }
            // input value is out of range
            else if (inputValue > 1)
            {
                // the shading has to be extended if extend[1] == true
                if (extend[1])
                {
                    inputValue = domain[1];
                }
                else
                {
                    if (getBackground() == null)
                    {
                        continue;
                    }
                    useBackground = true;
                }
            }
            int value;
            if (useBackground)
            {
                // use the given background color values
                value = getRgbBackground();
            }
            else
            {
                int key = (int) (inputValue * factor);
                value = colorTable[key];
            }
            int index = (j * w + i) * 4;
            data[index] = value & 255;
            value >>= 8;
            data[index + 1] = value & 255;
            value >>= 8;
            data[index + 2] = value & 255;
            data[index + 3] = 255;
        }
    }
    raster.setPixels(0, 0, w, h, data);
    return raster;
}

