public float getAverageFontWidth()
{
    if (Float.compare(averageWidth, 0) == 0)
    {
        float totalWidths = 0.0f;
        int characterCount = 0;
        if (widths != null)
        {
            for (Float width : widths.values())
            {
                if (width > 0)
                {
                    totalWidths += width;
                    ++characterCount;
                }
            }
        }
        if (characterCount != 0)
        {
            averageWidth = totalWidths / characterCount;
        }
        if (averageWidth <= 0 || Float.isNaN(averageWidth))
        {
            averageWidth = getDefaultWidth();
        }
    }
    return averageWidth;
}

public DecodeResult decode(InputStream encoded, OutputStream decoded,
                                     COSDictionary parameters, int index) throws IOException
{
    final COSDictionary decodeParams = getDecodeParams(parameters, index);

    try (FlateFilterDecoderStream decoderStream = new FlateFilterDecoderStream(encoded))
    {
        OutputStream wrapPredictor = Predictor.wrapPredictor(decoded, decodeParams);
        IOUtils.copy(decoderStream, wrapPredictor);
        wrapPredictor.flush();
    }
    return new DecodeResult(parameters);
}

protected void encode(InputStream input, OutputStream encoded, COSDictionary parameters)
        throws IOException
{
    int compressionLevel = getCompressionLevel();
    Deflater deflater = new Deflater(compressionLevel);
    try (DeflaterOutputStream out = new DeflaterOutputStream(encoded,deflater))
    {
        IOUtils.copy(input, out);
    }
    encoded.flush();
    deflater.end();
}

private static PDColorSpace createFromCOSObject(COSObject colorSpace, PDResources resources)
        throws IOException
{
    PDColorSpace cs;
    if (resources != null && resources.getResourceCache() != null)
    {
        ResourceCache resourceCache = resources.getResourceCache();
        cs = resourceCache.getColorSpace(colorSpace);
        if (cs != null)
        {
            return cs;
        }
    }
    cs = create(colorSpace.getObject(), resources);
    if (resources != null && resources.getResourceCache() != null && cs != null)
    {
        ResourceCache resourceCache = resources.getResourceCache();
        resourceCache.put(colorSpace, cs);
    }
    return cs;
}

