private boolean hasNoFollowingBinData() throws IOException
{
    // as suggested in PDFBOX-1164
    final int readBytes = source.read(binCharTestArr, 0, MAX_BIN_CHAR_TEST_LENGTH);
    boolean noBinData = true;
    int startOpIdx = -1;
    int endOpIdx = -1;
    String s = "";

    if (readBytes > 0)
    {
        for (int bIdx = 0; bIdx < readBytes; bIdx++)
        {
            final byte b = binCharTestArr[bIdx];
            if (b != 0 && b < 0x09 || b > 0x0a && b < 0x20 && b != 0x0d)
            {
                // control character or > 0x7f -> we have binary data
                noBinData = false;
                break;
            }
            // find the start of a PDF operator
            if (startOpIdx == -1 && !(b == 0 || b == 9 || b == 0x20 || b == 0x0a || b == 0x0d))
            {
                startOpIdx = bIdx;
            }
            else if (startOpIdx != -1 && endOpIdx == -1 &&
                     (b == 0 || b == 9 || b == 0x20 || b == 0x0a || b == 0x0d))
            {
                endOpIdx = bIdx;
            }
        }

        // PDFBOX-3742: just assuming that 1-3 non blanks is a PDF operator isn't enough
        if (noBinData && endOpIdx != -1 && startOpIdx != -1)
        {
            // usually, the operator here is Q, sometimes EMC (PDFBOX-2376), S (PDFBOX-3784),
            // or a number (PDFBOX-5957)
            s = new String(binCharTestArr, startOpIdx, endOpIdx - startOpIdx);
            if (!"Q".equals(s) && !"EMC".equals(s) && !"S".equals(s) &&
                !s.matches("^\\d*\\.?\\d*$"))
            {
                // operator is not Q, not EMC, not S, nur a number -> assume binary data
                noBinData = false;
            }
        }

        // only if not close to EOF
        if (noBinData && startOpIdx != -1 && readBytes == MAX_BIN_CHAR_TEST_LENGTH) 
        {
            if (endOpIdx == -1)
            {
                endOpIdx = MAX_BIN_CHAR_TEST_LENGTH;
                s = new String(binCharTestArr, startOpIdx, endOpIdx - startOpIdx);
            }
            // look for token of 3 chars max or a number
            if (endOpIdx - startOpIdx > 3 && !s.matches("^\\d*\\.?\\d*$"))
            {
                noBinData = false; // "operator" too long, assume binary data
            }
        }
        source.rewind(readBytes);
    }
    if (!noBinData)
    {
        LOG.warn("ignoring 'EI' assumed to be in the middle of inline image at stream offset " + 
                source.getPosition() + ", s = '" + s + "'");
    }
    return noBinData;
}

private boolean isSpaceOrReturn( int c )
{
    return c == 10 || c == 13 || c == 32;
}

public List<Object> parse() throws IOException
{
    List<Object> streamObjects = new ArrayList<>(100);
    Object token;
    while( (token = parseNextToken()) != null )
    {
        streamObjects.add( token );
    }
    return streamObjects;
}

private String readOperator() throws IOException
{
    skipSpaces();

    //average string size is around 2 and the normal string buffer size is
    //about 16 so lets save some space.
    StringBuilder buffer = new StringBuilder(4);
    int nextChar = source.peek();
    while(
        nextChar != -1 && // EOF
        !isWhitespace(nextChar) &&
        !isClosing(nextChar) &&
        nextChar != '[' &&
        nextChar != '<' &&
        nextChar != '(' &&
        nextChar != '/' &&
        nextChar != '%' &&
        (nextChar < '0' ||
         nextChar > '9' ) )
    {
        char currentChar = (char) source.read();
        nextChar = source.peek();
        buffer.append( currentChar );
        // Type3 Glyph description has operators with a number in the name
        if (currentChar == 'd' && (nextChar == '0' || nextChar == '1') ) 
        {
            buffer.append((char) source.read());
            nextChar = source.peek();
        }
    }
    return buffer.toString();
}

protected COSString parseCOSString() throws IOException
{
    char nextChar = (char) source.read();
    if (nextChar == '<')
    {
        return parseCOSHexString();
    }
    else if (nextChar != '(')
    {
        throw new IOException( "parseCOSString string should start with '(' or '<' and not '" +
                nextChar + "' at offset " + source.getPosition());
    }

    ByteArrayOutputStream out = new ByteArrayOutputStream();

    // This is the number of braces read
    int braces = 1;
    int c = source.read();
    while( braces > 0 && c != -1)
    {
        char ch = (char)c;
        int nextc = -2; // not yet read

        if (ch == ')')
        {

            braces--;
            braces = checkForEndOfString(braces);
            if( braces != 0 )
            {
                out.write(ch);
            }
        }
        else if (ch == '(')
        {
            braces++;
            out.write(ch);
        }
        else if( ch == '\\' )
        {
            //patched by ram
            char next = (char) source.read();
            switch(next)
            {
                case 'n':
                    out.write('\n');
                    break;
                case 'r':
                    out.write('\r');
                    break;
                case 't':
                    out.write('\t');
                    break;
                case 'b':
                    out.write('\b');
                    break;
                case 'f':
                    out.write('\f');
                    break;
                case ')':
                    // PDFBox 276 /Title (c:\)
                braces = checkForEndOfString(braces);
                    if( braces != 0 )
                    {
                        out.write(next);
                    }
                    else
                    {
                        out.write('\\');
                    }
                    break;
                case '(':
                case '\\':
                    out.write(next);
                    break;
                case ASCII_LF:
                case ASCII_CR:
                    //this is a break in the line so ignore it and the newline and continue
                    c = source.read();
                    while( isEOL(c) && c != -1)
                    {
                        c = source.read();
                    }
                    nextc = c;
                    break;
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                    StringBuilder octal = new StringBuilder();
                    octal.append( next );
                    c = source.read();
                    char digit = (char)c;
                    if( digit >= '0' && digit <= '7' )
                    {
                        octal.append( digit );
                        c = source.read();
                        digit = (char)c;
                        if( digit >= '0' && digit <= '7' )
                        {
                            octal.append( digit );
                        }
                        else
                        {
                            nextc = c;
                        }
                    }
                    else
                    {
                        nextc = c;
                    }

                    int character = 0;
                    try
                    {
                        character = Integer.parseInt( octal.toString(), 8 );
                    }
                    catch( NumberFormatException e )
                    {
                        throw new IOException( "Error: Expected octal character, actual='" + octal + "'", e );
                    }
                    out.write(character);
                    break;
                default:
                    // dropping the backslash
                    // see 7.3.4.2 Literal Strings for further information
                    out.write(next);
            }
        }
        else
        {
            out.write(ch);
        }
        if (nextc != -2)
        {
            c = nextc;
        }
        else
        {
            c = source.read();
        }
    }
    if (c != -1)
    {
        source.rewind(1);
    }
    return new COSString(out.toByteArray());
}

protected COSArray parseCOSArray() throws IOException
{
    long startPosition = source.getPosition();
    readExpectedChar('[');
    COSArray po = new COSArray();
    COSBase pbo;
    skipSpaces();
    int i;
    while (((i = source.peek()) > 0) && ((char) i != ']'))
    {
        pbo = parseDirObject();
        if( pbo instanceof COSObject )
        {
            // the current empty COSObject is replaced with the correct one
            pbo = null;
            // We have to check if the expected values are there or not PDFBOX-385
            if (po.size() > 1 && po.get(po.size() - 1) instanceof COSInteger)
            {
                COSInteger genNumber = (COSInteger)po.remove( po.size() -1 );
                if (po.size() > 0 && po.get(po.size() - 1) instanceof COSInteger)
                {
                    COSInteger number = (COSInteger)po.remove( po.size() -1 );
                    if (number.longValue() >= 0 && genNumber.intValue() >= 0)
                    {
                        COSObjectKey key = getObjectKey(number.longValue(),
                                genNumber.intValue());
                        pbo = getObjectFromPool(key);
                    }
                    else
                    {
                        LOG.warn("Invalid value(s) for an object key " + number.longValue()
                                + " " + genNumber.intValue());
                    }
                }
            }
        }
        // something went wrong
        if (pbo == null)
        {
            //it could be a bad object in the array which is just skipped
            LOG.warn("Corrupt array element at offset " + source.getPosition()
                    + ", start offset: " + startPosition);
            String isThisTheEnd = readString();
            // return immediately if a corrupt element is followed by another array
            // to avoid a possible infinite recursion as most likely the whole array is corrupted
            if (isThisTheEnd.isEmpty() && source.peek() == '[')
            {
                return po;
            }
            source.rewind(isThisTheEnd.getBytes(StandardCharsets.ISO_8859_1).length);
            // This could also be an "endobj" or "endstream" which means we can assume that
            // the array has ended.
            if(ENDOBJ_STRING.equals(isThisTheEnd) || ENDSTREAM_STRING.equals(isThisTheEnd))
            {
                return po;
            }
        }
        else
        {
            po.add(pbo);
        }
        skipSpaces();
    }
    // read ']'
    source.read();
    skipSpaces();
    return po;
}

protected COSName parseCOSName() throws IOException
{
    readExpectedChar('/');
    ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    int c = source.read();
    while (!isEndOfName(c))
    {
        final int ch = c;
        if (ch == '#')
        {
            int ch1 = source.read();
            int ch2 = source.read();
            // Prior to PDF v1.2, the # was not a special character.  Also,
            // it has been observed that various PDF tools do not follow the
            // spec with respect to the # escape, even though they report
            // PDF versions of 1.2 or later.  The solution here is that we
            // interpret the # as an escape only when it is followed by two
            // valid hex digits.
            if (isHexDigit((char)ch1) && isHexDigit((char)ch2))
            {
                String hex = Character.toString((char) ch1) + (char) ch2;
                try
                {
                    buffer.write(Integer.parseInt(hex, 16));
                }
                catch (NumberFormatException e)
                {
                    throw new IOException("Error: expected hex digit, actual='" + hex + "'", e);
                }
                c = source.read();
            }
            else
            {
                // check for premature EOF
                if (ch2 == -1 || ch1 == -1)
                {
                    LOG.error("Premature EOF in BaseParser#parseCOSName");
                    c = -1;
                    break;
                }
                source.rewind(1);
                c = ch1;
                buffer.write(ch);
            }
        }
        else
        {
            buffer.write(ch);
            c = source.read();
        }
    }
    if (c != -1)
    {
        source.rewind(1);
    }

    return COSName.getPDFName(decodeBuffer(buffer));
}

protected boolean isClosing(int c)
{
    return c == ']';
}

