private Tokenizer(CharSequence text, SyntaxHandler syntaxHandler)
{
    this.input = text;
    this.handler = syntaxHandler;
}

private char currentChar()
{
    return input.charAt(index);
}

private boolean hasMore()
{
    return index < input.length();
}

private char nextChar()
{
    index++;
    if (!hasMore())
    {
        return EOT;
    }
    else
    {
        return currentChar();
    }
}

private State nextState()
{
    char ch = currentChar();
    switch (ch)
    {
    case CR:
    case LF:
    case FF: //FF
        state = State.NEWLINE;
        break;
    case NUL:
    case TAB:
    case SPACE:
        state = State.WHITESPACE;
        break;
    case '%':
        state = State.COMMENT;
        break;
    default:
        state = State.TOKEN;
    }
    return state;
}

private char peek()
{
    if (index < input.length() - 1)
    {
        return input.charAt(index + 1);
    }
    else
    {
        return EOT;
    }
}

private void scanComment()
{
    assert state == State.COMMENT;
    buffer.append(currentChar());
    loop:
    while (hasMore())
    {
        char ch = nextChar();
        switch (ch)
        {
        case CR:
        case LF:
        case FF:
            break loop;
        default:
            buffer.append(ch);
        }
    }
    //EOF reached
    handler.comment(buffer);
}

private void scanNewLine()
{
    assert state == State.NEWLINE;
    char ch = currentChar();
    buffer.append(ch);
    if (ch == CR && peek() == LF)
    {
        //CRLF is treated as one newline
        buffer.append(nextChar());
    }
    handler.newLine(buffer);
    nextChar();
}

private void scanToken()
{
    assert state == State.TOKEN;
    char ch = currentChar();
    buffer.append(ch);
    switch (ch)
    {
    case '{':
    case '}':
        handler.token(buffer);
        nextChar();
        return;
    default:
        //continue
    }
    loop:
    while (hasMore())
    {
        ch = nextChar();
        switch (ch)
        {
        case NUL:
        case TAB:
        case SPACE:
        case CR:
        case LF:
        case FF:
        case EOT:
        case '{':
        case '}':
            break loop;
        default:
            buffer.append(ch);
        }
    }
    //EOF reached
    handler.token(buffer);
}

private void scanWhitespace()
{
    assert state == State.WHITESPACE;
    buffer.append(currentChar());
    loop:
    while (hasMore())
    {
        char ch = nextChar();
        switch (ch)
        {
        case NUL:
        case TAB:
        case SPACE:
            buffer.append(ch);
            break;
        default:
            break loop;
        }
    }
    handler.whitespace(buffer);
}

private void tokenize()
{
    while (hasMore())
    {
        buffer.setLength(0);
        nextState();
        switch (state)
        {
        case NEWLINE:
            scanNewLine();
            break;
        case WHITESPACE:
            scanWhitespace();
            break;
        case COMMENT:
            scanComment();
            break;
        default:
            scanToken();
        }
    }
}

