protected Map<Integer, Integer> getGIDToCode() throws IOException
{
    if (gidToCode != null)
    {
        return gidToCode;
    }

    gidToCode = new HashMap<>();
    for (int code = 0; code <= 255; code++)
    {
        int gid = codeToGID(code);
        if (!gidToCode.containsKey(gid))
        {
            gidToCode.put(gid, code);
        }
    }
    return gidToCode;
}

