public void close() throws IOException
{
    try
    {
        flush();
        super.close();
    }
    finally
    {
        indata = outdata = null;
    }
}

public void flush() throws IOException
{
    if (flushed)
    {
        return;
    }
    if (count > 0)
    {
        for (int i = count; i < 4; i++)
        {
            indata[i] = 0;
        }
        transformASCII85();
        if (outdata[0] == Z)
        {
            for (int i = 0; i < 5; i++) // expand 'z',
            {
                outdata[i] = (byte) OFFSET;
            }
        }
        for (int i = 0; i < count + 1; i++)
        {
            out.write(outdata[i]);
            if (--lineBreak == 0)
            {
                out.write(NEWLINE);
                lineBreak = maxline;
            }
        }
    }
    if (--lineBreak == 0)
    {
        out.write(NEWLINE);
    }
    out.write(terminator);
    out.write('>');
    out.write(NEWLINE);
    count = 0;
    lineBreak = maxline;
    flushed = true;
    super.flush();
}

